generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?metric (COUNT(DISTINCT ?entity) AS ?count) WHERE {
  { ?entity a wm:InvestmentGoal . BIND("goalCount" AS ?metric) }
  UNION
  { ?entity a wm:PortfolioHolding . BIND("holdingCount" AS ?metric) }
  UNION
  { ?entity a wm:CashFlow . BIND("transactionCount" AS ?metric) }
  UNION
  { ?entity a wm:RebalancingAction . BIND("rebalanceCount" AS ?metric) }
  UNION
  { ?entity a wm:ScenarioRebalancing . BIND("scenarioCount" AS ?metric) }
}
GROUP BY ?metric

